{
  "plan": "O programa set_value verifica explicitamente que data_account é o PDA canônico derivado de [b"data", user.key] via require_keys_eq!, então a hipótese de PDA não canônico deve ser rejeitada. Vou montar um cenário com uma conta DataAccount existente no endereço canônico e um usuário signer, executar o baseline legítimo (deve ter sucesso) e então atacar passando uma conta DataAccount em um endereço com bump não canônico (primeiro bump abaixo do canônico que gera endereço válido). O efeito medido seria que a conta não canônica foi aceita e teve seus campos escritos, mas como o require_keys_eq! bloqueia, o ataque deve falhar.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, _canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontra um bump não canônico que gera um endereço válido
let mut non_canonical_pda = Pubkey::default();
let mut found = false;
let mut b: u8 = 255;
while b > 0 {
    if let Ok(pk) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id) {
        if pk != canonical_pda {
            non_canonical_pda = pk;
            found = true;
            break;
        }
    }
    b -= 1;
}

let data_canonical = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, _canonical_bump)),
    None,
);
let data_non_canonical = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, b)),
    None,
);
let user_acc = wallet(1_000_000_000);

// Baseline legítimo: usa o PDA canônico
let ix_baseline = env.anchor_ix(
    "set_value",
    &(42u64,),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_baseline = vec![
    (canonical_pda, data_canonical.clone()),
    (user, user_acc.clone()),
];
let r_base = env.baseline("set_value legítimo no PDA canônico", &ix_baseline, &contas_baseline);

// Ataque: usa endereço não canônico
let ix_attack = env.anchor_ix(
    "set_value",
    &(42u64,),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_attack = vec![
    (non_canonical_pda, data_non_canonical),
    (user, user_acc),
];
let r = env.attack("set_value com PDA não canônico", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let acc = after(&r, &non_canonical_pda);
    let value = read_u64(acc.data(), 40);
    env.effect(
        "conta em endereço não canônico foi aceita e escrita",
        value == 42u64,
    );
}"
